{"packet_id":"D005-01","doc_id":"D005","jurisdiction":"CA","category":"application_screening_fees","lifecycle":"enacted","title":"California tenant screening fee cap and applicant rights","requirement":"A landlord may charge no more than the $68.96 screening fee cap for 2026, must document costs and refund unused amounts, must not charge when no unit is available or keep the fee of an applicant not selected, and must accept a reusable screening report.","key_value":"$68.96 for 2026","coverage_conditions":"Applies to landlords charging a screening fee to a prospective tenant; the page states no building age, unit count or ownership limits.","applicability":{"conditions":[],"per_tenancy":"Applies where a landlord charges a prospective tenant a screening or application fee.","coverage_quotes":[]},"exemptions":null,"penalty":null,"effective_date":"2026","valid_through":"2026","citation":"Cal. Civ. Code § 1950.6","quoted_span":"The maximum tenant screening fee for 2026 is\n$68.96","interaction":null,"relations":[],"confidence":0.8,"conflict_flag":false,"conflict_note":null}
{"packet_id":"D005-01","doc_id":"D005","jurisdiction":"Berkeley, CA","category":"application_screening_fees","lifecycle":"enacted","title":"Berkeley tenant screening and application fee rules","requirement":"An owner charging a screening fee must give applicants a screening fee rights statement and the state fee cap before taking the fee, and may not charge an existing tenant a non-refundable fee to renew a tenancy or to add or replace a roommate.","key_value":null,"coverage_conditions":"Chapter 13.78 applies to all residential rental agreements regardless of contrary lease language; violating lease provisions are unenforceable.","applicability":{"conditions":[],"per_tenancy":"Applies to all residential rental agreements; the non-refundable fee ban covers fees charged to existing tenants.","coverage_quotes":[]},"exemptions":null,"penalty":"Any provision of an existing rental agreement or lease that violates this chapter is unenforceable.","effective_date":null,"valid_through":null,"citation":"Berkeley Mun. Code ch. 13.78","quoted_span":"An owner of residential rental property (or the owner’s agent) cannot charge a non-refundable fee to any existing tenant for the purpose of renewing a tenancy, in whole or in part, including any fee associated with the departure of a roommate or to request to add or replace a roommate in a pre-existing household.","interaction":null,"relations":[],"confidence":0.8,"conflict_flag":false,"conflict_note":null}
